#!/usr/bin/env python3
"""Check system includes using compile databases generated by this repo's CMake.

Only recognized preprocessing options are forwarded. Response files, compiler
configuration options and compiler pass-through arguments are refused.
"""

import argparse
import codecs
import json
import os
import re
import shlex
import subprocess
import sys
import tempfile
from functools import lru_cache
from pathlib import Path


LINEMARKER = re.compile(rb'^#\s+\d+\s+"((?:\\.|[^"\\])*)"((?:\s+\d+)*)\s*$')
# These options take a separate operand. The value is the separator for their
# joined form, or None when the compiler only accepts a separate operand.
FORWARDED_VALUE_OPTIONS = {
    "-I": "", "-isystem": "", "-iquote": "", "-idirafter": "",
    "-D": "", "-U": "", "-include": "", "-imacros": "",
    "-isysroot": "", "--sysroot": "=", "-target": None, "-arch": None, "-x": "",
}
DISCARDED_VALUE_OPTIONS = {
    "-o": "", "-MF": "", "-MT": "", "-MQ": "", "-MJ": "",
    "-serialize-diagnostics": "=", "--serialize-diagnostics": "=",
    "-gen-cdb-fragment-path": "=", "-fcrash-diagnostics-dir": "=", "-fmodules-cache-path": "=",
    "-include-pch": "=", "-include-pth": "=", "-isystem-after": None,
    "-dependency-file": "=", "-resource-dir": "=", "-working-directory": "=",
    "-mllvm": "=", "-mmlir": "=", "-Xassembler": None, "-Xlinker": None,
}
VALUE_OPTIONS = FORWARDED_VALUE_OPTIONS | DISCARDED_VALUE_OPTIONS
JOINED_VALUE_OPTIONS = tuple(sorted(
    ((option + separator, option) for option, separator in VALUE_OPTIONS.items() if separator is not None),
    key=lambda item: len(item[0]),
    reverse=True,
))

FORWARDED_EQUALS_OPTIONS = (
    "--target=", "-std=", "-stdlib=",
    "-march=", "-mcpu=", "-mtune=", "-mabi=", "-mfpu=", "-mfloat-abi=",
    "-mbranch-protection=", "-mmacosx-version-min=", "-mmacos-version-min=", "-mios-version-min=",
    "-miphoneos-version-min=", "-mios-simulator-version-min=",
)
TARGET_FEATURES = {
    "3dnow", "3dnowa", "adx", "aes", "altivec", "avx", "avx2", "avx512bf16", "avx512bitalg",
    "avx512bw", "avx512cd", "avx512dq", "avx512f", "avx512fp16", "avx512ifma", "avx512vbmi",
    "avx512vbmi2", "avx512vl", "avx512vnni", "avx512vpopcntdq", "bmi", "bmi2", "crc",
    "f16c", "fma", "fma4", "lzcnt", "mmx", "neon", "outline-atomics", "pclmul", "popcnt",
    "red-zone", "sha", "sse", "sse2", "sse3", "sse4", "sse4.1", "sse4.2", "sse4a", "ssse3",
    "strict-align", "unaligned-access", "xsave", "xsavec", "xsaveopt", "xsaves",
}
FORWARDED_FLAGS = {
    "-nostdinc", "-nostdinc++", "-nostdlibinc", "-nobuiltininc", "-pthread",
    "-m32", "-m64", "-mx32", "-marm", "-mthumb", "-mbig-endian", "-mlittle-endian",
    "-msoft-float", "-mhard-float",
    "-fexceptions", "-fno-exceptions", "-fcxx-exceptions", "-fno-cxx-exceptions",
    "-fobjc-exceptions", "-fno-objc-exceptions", "-frtti", "-fno-rtti",
    "-fpic", "-fPIC", "-fno-pic", "-fno-PIC", "-fpie", "-fPIE", "-fno-pie", "-fno-PIE",
    "-fchar8_t", "-fno-char8_t", "-fsigned-char", "-funsigned-char", "-fno-signed-char",
    "-fno-unsigned-char", "-fms-extensions", "-fno-ms-extensions",
} | {prefix + feature for feature in TARGET_FEATURES for prefix in ("-m", "-mno-")}
OPTIMIZATION_OR_WARNING = re.compile(r"-O(?:[0-9]+|g|s|z|fast)?|-W[A-Za-z][A-Za-z0-9+-]*")
REFUSED_OPTIONS = {"--config", "-Xclang", "-Xpreprocessor", "-Xarch", "-Wp"}


def preprocess_command(entry, output):
    arguments = entry["arguments"] if "arguments" in entry else shlex.split(entry["command"])
    if not arguments or not arguments[0]:
        raise ValueError("missing compiler in compile command")
    # The driver expands bare response arguments before it consumes option values.
    for argument in arguments[1:]:
        if argument.startswith("@"):
            raise ValueError(f"unsupported compiler response file argument: {argument}")

    command = [arguments[0]]
    saw_compile = False
    operands = iter(arguments[1:])
    for argument in operands:
        if argument == "--":
            break
        if argument.partition("=")[0] in REFUSED_OPTIONS or argument.startswith(("-Xarch_", "-Wp,")):
            raise ValueError(f"unsupported compiler option: {argument}")
        if argument in VALUE_OPTIONS:
            value = next(operands, None)
            if value is None:
                raise ValueError(f"missing value for {argument}")
            if argument in FORWARDED_VALUE_OPTIONS:
                command.extend((argument, value))
        elif argument == "-c":
            saw_compile = True
        else:
            option = next((name for prefix, name in JOINED_VALUE_OPTIONS if argument.startswith(prefix)), None)
            if option is not None:
                if option in FORWARDED_VALUE_OPTIONS:
                    command.append(argument)
            elif (argument.startswith(FORWARDED_EQUALS_OPTIONS) or argument in FORWARDED_FLAGS
                  or OPTIMIZATION_OR_WARNING.fullmatch(argument)):
                command.append(argument)
    if not saw_compile:
        raise ValueError("expected a Clang or GCC compile command with -c")

    # The database names the sole input. Preserve its spelling unless the driver
    # would interpret it as an option or expand it as a response file.
    source = entry["file"]
    if source.startswith(("-", "@")):
        source = "./" + source
    return [*command, "-E", "-o", str(output), source]


@lru_cache(maxsize=4096)
def marker_path(directory, spelling):
    if not spelling or (spelling.startswith(b"<") and spelling.endswith(b">")):
        return None
    decoded, _ = codecs.escape_decode(spelling)
    return (directory / os.fsdecode(decoded)).resolve()


def check_translation_unit(entry, directory, source, vendor):
    with tempfile.TemporaryDirectory(prefix="khaoz-include-check-") as scratch:
        output = Path(scratch) / "preprocessed"
        command = preprocess_command(entry, output)
        environment = {**os.environ, "TMPDIR": scratch, "TMP": scratch, "TEMP": scratch}
        status = subprocess.run(command, cwd=directory, env=environment).returncode
        if status != 0:
            raise ValueError(f"preprocessor exited {status}")
        with output.open("rb") as lines:
            return check_linemarkers(lines, directory, source, vendor)


def check_linemarkers(lines, directory, source, vendor):
    stack = []
    reported = set()
    saw_source = False
    for line in lines:
        match = LINEMARKER.fullmatch(line)
        if match is None:
            continue
        path = marker_path(directory, match[1])
        flags = match[2].split()
        saw_source |= path == source

        # Flag 1 enters a file. Flag 2 returns to its includer.
        if b"2" in flags and stack:
            stack.pop()
        if b"1" in flags or not stack:
            stack.append(path)
        else:
            stack[-1] = path

        if b"3" in flags or path is None or not path.is_relative_to(vendor) or path in reported:
            continue
        reported.add(path)
        print(f"{source}: vendored header is not a system header: {path}", file=sys.stderr)
        chain = " -> ".join(str(item) for item in stack if item is not None)
        print(f"  include chain: {chain}", file=sys.stderr)

    if not saw_source:
        raise ValueError("preprocessor did not emit linemarkers for the source file")
    return not reported


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("-p", required=True, type=Path, metavar="BUILD_DIR")
    build = parser.parse_args().p.resolve()
    vendor = (Path(__file__).resolve().parents[1] / "third_party").resolve()

    subject = build / "compile_commands.json"
    try:
        entries = json.loads(subject.read_text(encoding="utf-8"))
        failed = False
        checked = 0
        for entry in entries:
            directory = (build / entry["directory"]).resolve()
            source = (directory / entry["file"]).resolve()
            if source.is_relative_to(vendor):
                continue
            subject = source
            checked += 1
            if not check_translation_unit(entry, directory, source, vendor):
                failed = True
        if checked == 0:
            raise ValueError("compilation database contains no first-party translation units")
    except (OSError, KeyError, TypeError, ValueError) as error:
        print(f"{subject}: {error}", file=sys.stderr)
        return 1
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())
